const base = String(env.get("EOS_BASE_URL") || "").replace(/\/$/, "");
if (!/^https?:\/\/[^/]+(?:\/.*)?$/.test(base)) {
    node.error("Configure EOS_BASE_URL before checking prices", msg);
    return null;
}
const start = new Date();
start.setHours(0, 0, 0, 0);
const end = new Date(start);
end.setDate(end.getDate() + 1);
msg.rcPriceWindow = {start: start.getTime(), end: end.getTime()};
msg.method = "GET";
msg.url = base + "/v1/prediction/series?key=elecprice_marketprice_raw_wh&processing=raw"
    + "&start_datetime=" + encodeURIComponent(start.toISOString())
    + "&end_datetime=" + encodeURIComponent(end.toISOString());
delete msg.payload;
delete msg.headers;
return msg;

const now = Date.now();
const window = msg.rcPriceWindow;
const validWindow = window && Number.isFinite(window.start) && Number.isFinite(window.end)
    && window.end > window.start && now >= window.start && now < window.end;
const interval = 900000;
const expected = validWindow ? (window.end - window.start) / interval : 0;
const idx = validWindow ? Math.floor((now - window.start) / interval) : 0;
const values = msg.payload && msg.payload.data;
const finite = value => typeof value === "number" && Number.isFinite(value);
const entries = values && typeof values === "object" && !Array.isArray(values) ? Object.entries(values) : null;
const validValues = entries && entries.every(([time, value]) => Number.isFinite(Date.parse(time))
    && (value === null || finite(value)));
const prices = new Map(validValues ? entries.map(([time, value]) => [Date.parse(time), value]) : []);
let remaining = 0;
if (validWindow && Number.isInteger(expected)) {
    for (let i = idx; i < expected; i++) {
        if (finite(prices.get(window.start + i * interval))) remaining++;
    }
}
const complete = msg.statusCode === 200 && validWindow && validValues
    && Number.isInteger(expected) && expected > idx && remaining === expected - idx;
flow.set("rcPriceCoverage", {
    time: now,
    date: validWindow ? new Date(window.start).toDateString() : null,
    complete: !!complete,
    current_slot: idx,
    expected_slots: expected,
    remaining_source_slots: remaining
});
if (complete) {
    return msg.topic === "rc_optimize" ? [null, {topic: "rc_optimize"}] : null;
}
flow.set("rcError", {time: now, message: "EOS raw prices are missing for today's remaining slots"});
const empty = msg.statusCode === 200 && validWindow && validValues
    && !Array.from(prices).some(([time, value]) => time >= window.start && time < window.end && finite(value));
const previous = flow.get("rcPredictionRecovery");
if (empty && !flow.get("rcBusy") && (!previous || now - previous.started >= 300000)) {
    const base = String(env.get("EOS_BASE_URL") || "").replace(/\/$/, "");
    if (!/^https?:\/\/[^/]+(?:\/.*)?$/.test(base)) {
        node.error("Configure EOS_BASE_URL before updating predictions", msg);
        return null;
    }
    flow.set("rcPredictionRecovery", {started: now, status: "loading"});
    node.status({fill: "yellow", shape: "ring", text: "Loading EOS predictions"});
    return [{method: "POST", url: base + "/v1/prediction/update", payload: "{}",
        headers: {"Content-Type": "application/json"}}, null];
}
node.error("EOS raw price coverage check failed", msg);
return null;

const state = flow.get("rcPredictionRecovery") || {};
flow.set("rcPredictionRecovery", {...state, finished: Date.now(),
    status: msg.statusCode === 200 ? "loaded" : "failed", http_status: msg.statusCode});
if (msg.statusCode !== 200) {
    node.error("EOS prediction update failed: " + msg.statusCode, msg);
    return null;
}
return {topic: "refresh"};
